fn project(value:&SemioModelSnapshot)->SqliteDatabase{semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(SqliteDatabaseLimits::default(), &mut |_|true, |control| value.to_sqlite_database(control)).unwrap()}
