fn sqlite_snapshot_semio_model_all_enums_spatial_geometry_properties_relationships_and_native_state(){let snapshot=fixture();let bytes=export_sqlite_database(&project(&snapshot),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let restored=restore(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(restored,snapshot);assert_eq!(<SemioModelSnapshot as pack::snapshot::ArtifactPack>::encode_pack(&restored),<SemioModelSnapshot as pack::snapshot::ArtifactPack>::encode_pack(&snapshot));assert_eq!(<SemioModelSnapshot as pack::snapshot::ArtifactDsl>::print_dsl(&restored),<SemioModelSnapshot as pack::snapshot::ArtifactDsl>::print_dsl(&snapshot));assert_eq!(restore(&project(&SemioModelSnapshot::default())).unwrap(),SemioModelSnapshot::default());}
#[test]
fn sqlite_snapshot_semio_model_rejects_cycles_dangling_refs_variant_shapes_and_limits(){let original=project(&fixture());for change in 0..5{let mut db=original.clone();match change{0=>db.table_mut("semio_model_spatial").unwrap().rows[0].values[3]=SqliteValue::Integer(4),1=>db.table_mut("semio_model_relation").unwrap().rows[0].values[6]=SqliteValue::Integer(999),2=>db.table_mut("semio_model_element").unwrap().rows[0].values[2]=SqliteValue::Text("unexpected".into()),3=>db.table_mut("semio_model_property").unwrap().rows[0].values[7]=SqliteValue::Integer(1),_=>db.table_mut("semio_model_geometry_reference").unwrap().rows[0].values[2]=SqliteValue::Text("unexpected".into())}assert!(restore(&db).is_err());}let limits=SqliteDatabaseLimits{max_rows:1,max_value_bytes:1,..SqliteDatabaseLimits::default()};assert!(semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(limits, &mut |_|true, |control| fixture().to_sqlite_database(control)).is_err());assert!(semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(limits, &mut |_|true, |control| SemioModelSnapshot::from_sqlite_database(&original,control)).is_err());assert!(semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(SqliteDatabaseLimits::default(), &mut |_|false, |control| fixture().to_sqlite_database(control)).is_err());}
#[test]
fn sqlite_snapshot_semio_model_independent_relationship_join_property_edit_and_validator(){use std::io::Write;use std::process::{Command,Stdio};let bytes=export_sqlite_database(&project(&fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const r=db.query('SELECT s.native_id source,t.native_id target FROM semio_model_relation JOIN semio_model_entity s ON s.id=source_entity_id JOIN semio_model_entity t ON t.id=target_entity_id WHERE semio_model_relation.ordinal=0').get();if(r.source!=='spatial-0'||r.target!=='element-0')throw Error('entities');db.query(\"UPDATE semio_model_property SET text_value='independently edited' WHERE kind='text' AND property_set_id=1\").run();await Bun.write(Bun.stdout,db.serialize());db.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let restored=restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();let mut expected=fixture();expected.elements[0].psets[0].properties[0].value=PsetValue::Text{value:"independently edited".into()};assert_eq!(restored,expected);assert!(semio_s_artifact_stdio_semio_model::io::semio_model_referential_diagnostics(&restored).is_empty());}

