fn sqlite_snapshot_semio_model_bare_owner_capability_native_payload_bridge(){let snapshot=fixture();let payload=store::io::IoPayload::Binary(<SemioModelSnapshot as pack::snapshot::ArtifactPack>::encode_pack(&snapshot));let codec=store::bare_artifact_codec::<SemioModelSnapshot,semio_s_artifact_stdio_semio_model::schema::mutations::SemioModelMutation>("s.stdio.semio.model");let provider=codec.snapshot_sqlite.expect("owner must publish typed SQLite capability");assert_eq!(provider.snapshot_type,Some(std::any::TypeId::of::<SemioModelSnapshot>()));let dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"model".into()};let db=semio_s_artifact_stdio_contract::testing::with_decoding(|native_owner| (provider.export)("s.stdio.semio.model",&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()), native_owner)).unwrap().value;let bytes=export_sqlite_database(&db,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let db=import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let actual=semio_s_artifact_stdio_contract::testing::with_encoding(|native_owner| (provider.import)("s.stdio.semio.model",&dialect,&mut Some(db),SnapshotEncoding::Binary,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()), native_owner)).unwrap().value;assert_eq!(actual,payload);}

