fn sqlite_snapshot_semio_model_explicit_controlled_native_owner(){use store::{pack::snapshot::ArtifactPack,pack::snapshot::ArtifactDsl};let f:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let expected=fixture();for payload in [store::io::IoPayload::Binary(expected.encode_pack()),store::io::IoPayload::Text(expected.print_dsl())]{let actual=semio_s_artifact_stdio_contract::testing::with_decoding(|native_owner| SemioModelSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()), native_owner)).unwrap();assert_eq!(actual,expected);assert!(semio_s_artifact_stdio_contract::testing::with_decoding(|native_owner| SemioModelSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default()), native_owner)).is_err());assert!(semio_s_artifact_stdio_contract::testing::with_decoding(|native_owner| SemioModelSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:f["nativeAdmission"]["tinyBudgetBytes"].as_u64().unwrap() as usize,..SqliteDatabaseLimits::default()}), native_owner)).is_err());assert!(semio_s_artifact_stdio_contract::testing::with_decoding(|native_owner| SemioModelSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:2,..SqliteDatabaseLimits::default()}), native_owner)).is_err());}let count=f["nativeAdmission"]["collectionItems"].as_u64().unwrap() as usize;let canceled=f["nativeAdmission"]["cancelAfter"].as_u64().unwrap() as usize;let value=SemioModelSnapshot{elements:vec![SemioModelElement{id:"element".into(),psets:vec![PropertySet{name:"".into(),properties:(0..count).map(|_|Property{key:"".into(),value:PsetValue::Text{value:"".into()}}).collect()}],..SemioModelElement::default()}],..SemioModelSnapshot::default()};for payload in [store::io::IoPayload::Binary(value.encode_pack()),store::io::IoPayload::Text(value.print_dsl())]{let mut interior=false;let mut callback=|p:SqliteSnapshotProgress|{if p.phase==SqliteSnapshotPhase::DecodeNative&&p.total==count&&p.completed==canceled{interior=true;false}else{true}};assert!(semio_s_artifact_stdio_contract::testing::with_decoding(|native_owner| SemioModelSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default()), native_owner)).is_err());assert!(interior);}}

