   for short in[SqliteDatabaseLimits{max_rows:limits.max_rows-1,..limits},SqliteDatabaseLimits{max_value_bytes:limits.max_value_bytes-1,..limits},SqliteDatabaseLimits{max_schema_bytes:limits.max_schema_bytes-1,..limits},SqliteDatabaseLimits{max_tables:8,..limits},SqliteDatabaseLimits{max_columns:30,..limits}]{assert!(semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(short, &mut |_|true, |control| source.to_sqlite_database(control)).is_err(),"relational copied limits {short:?}");assert!(semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(short, &mut |_|true, |control| SemioModelSnapshot::from_sqlite_database(&database,control)).is_err(),"reconstruct copied limits {short:?}");assert!(semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(short, &mut |_|true, |control| source.preflight_sqlite_snapshot_encoding(encoding,control)).is_err(),"preflight copied limits {encoding:?} {short:?}");assert!(semio_s_artifact_stdio_contract::testing::with_encoding(|native_owner| source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,short), native_owner)).is_err(),"encoder copied limits {encoding:?} {short:?}");assert!(semio_s_artifact_stdio_contract::testing::with_decoding(|native_owner| SemioModelSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,short), native_owner)).is_err(),"decoder copied limits {encoding:?} {short:?}");}
