/// 🧾️ Reuses the independent full Model fixture with exact measured semantic grants and authored long schema.
fn norm_late_owned_model()->(SemioModelSnapshot,SqliteDatabase,SqliteDatabaseLimits,serde_json::Value){
 let contract:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🧯️late-owned.json")).unwrap();
 let mut source=fixture();source.schema=contract["schemaText"]["character"].as_str().unwrap().repeat(contract["schemaText"]["count"].as_u64().unwrap()as usize);
 let limits=SqliteDatabaseLimits{max_rows:contract["rows"].as_u64().unwrap()as usize,max_value_bytes:contract["valueBytes"].as_u64().unwrap()as usize,max_schema_bytes:contract["schemaBytes"].as_u64().unwrap()as usize,max_tables:9,max_columns:31,..SqliteDatabaseLimits::default()};
 let extent=norm_independent_complete_extent(&source);for key in["rows","valueBytes","schemaBytes","tableWidths"]{assert_eq!(extent[key],contract[key],"independent late Model {key}");}
 let database=semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(limits, &mut |_|true, |control| source.to_sqlite_database(control)).unwrap();(source,database,limits,contract)
}

#[test]
fn sqlite_snapshot_semio_model_nonempty_reconstruction_exact_backing_admission(){
 use semio_framework_io_sqlite_snapshot_testing_backing::measure;
 let(source,database,limits,_)=norm_late_owned_model();let mut callback=|_|true;let mut control=SqliteSnapshotControl::new(&mut callback,limits);
 let(result,observed)=measure(||SemioModelSnapshot::from_sqlite_database(&database,&mut control));let restored=result.unwrap();
 assert!(observed.bytes>0&&observed.requests>0);assert_eq!(limits.max_allocation_bytes-control.allocation_remaining_bytes(),observed.bytes,"every concrete reconstruction request admitted");
 assert_eq!(semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(limits, &mut |_|true, |control| restored.to_sqlite_database(control)).unwrap(),database);restored.retire_sqlite_snapshot();
 let exact=SqliteDatabaseLimits{max_allocation_bytes:observed.bytes,..limits};let mut callback=|_|true;let mut control=SqliteSnapshotControl::new(&mut callback,exact);
 let(result,replayed)=measure(||SemioModelSnapshot::from_sqlite_database(&database,&mut control));let restored=result.unwrap();assert_eq!(replayed.bytes,observed.bytes);assert_eq!(control.allocation_remaining_bytes(),0);restored.retire_sqlite_snapshot();
 for maximum in[0,observed.bytes-1]{
  let mut callback=|_|true;let mut control=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits{max_allocation_bytes:maximum,..limits});
  let(kind,observed)=measure(||{match SemioModelSnapshot::from_sqlite_database(&database,&mut control){Err(error)=>{let kind=error.kind;drop(error);kind},Ok(value)=>{value.retire_sqlite_snapshot();panic!("short concrete backing allowance admitted");}}});
  assert_eq!(kind,ValueRefusalKind::OwnershipLimit);assert_eq!(observed.bytes,observed.released_bytes,"all refused backing including diagnostic and retirement scratch released");
 }
 source.retire_sqlite_snapshot();
}

#[test]
fn sqlite_snapshot_semio_model_nonempty_reconstruction_late_schema_cancel_cleanup(){
 use semio_framework_io_sqlite_snapshot_testing_backing::{measure,active_request_bytes};
 let(source,database,limits,contract)=norm_late_owned_model();let completed=contract["cancellation"]["completed"].as_u64().unwrap()as usize;let total=contract["cancellation"]["total"].as_u64().unwrap()as usize;
 for interior in[false,true]{
  let mut reached=false;let mut backing_at_cancel=0;let mut callback=|event:SqliteSnapshotProgress|{
   let cancel=if interior{event.phase==SqliteSnapshotPhase::ReconstructSnapshot&&event.total==total&&event.completed==completed&&active_request_bytes()>0}else{true};
   if cancel{reached=true;backing_at_cancel=active_request_bytes();} !cancel
  };let mut control=SqliteSnapshotControl::new(&mut callback,limits);
  let((kind,diagnostic),observed)=measure(||{match SemioModelSnapshot::from_sqlite_database(&database,&mut control){Err(error)=>{let result=(error.kind,match &error.message{std::borrow::Cow::Owned(message)=>message.capacity(),std::borrow::Cow::Borrowed(_)=>0});drop(error);result},Ok(value)=>{value.retire_sqlite_snapshot();panic!("authored reconstruction cancellation ignored");}}});
  assert!(reached);assert_eq!(kind,ValueRefusalKind::Canceled);assert_eq!(observed.bytes,observed.released_bytes,"all canceled backing including retirement scratch released");
  if interior{assert!(backing_at_cancel>0&&observed.bytes>diagnostic,"late cancellation followed concrete nonempty ownership");}
 }
 source.retire_sqlite_snapshot();
}
